-- Who reads sales documents: the owner, whoever keeps or checks the books, and the sales team.
-- A salesperson reads only the documents they wrote and the ones that are theirs. A member
-- limited to some branches reads only those branches' documents. Who writes them: the owner, an
-- accountant and the sales team, under the same limits.
CREATE POLICY sales_documents_select ON public.sales_documents FOR SELECT TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor', 'sales_manager', 'salesperson')
    AND ((SELECT app.tenant_role()) <> 'salesperson' OR created_by = (SELECT app.current_user_id()) OR salesperson_id = (SELECT app.current_user_id()))
    AND ((SELECT app.tenant_branch_ids()) IS NULL OR branch_id = ANY ((SELECT app.tenant_branch_ids())::uuid[]))
  );
--> statement-breakpoint
CREATE POLICY sales_documents_insert ON public.sales_documents FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'sales_manager', 'salesperson')
    AND ((SELECT app.tenant_branch_ids()) IS NULL OR branch_id = ANY ((SELECT app.tenant_branch_ids())::uuid[]))
    AND kind IN ('quotation', 'order')
    AND status = 'draft'
    AND created_by = (SELECT app.current_user_id())
    AND updated_by = (SELECT app.current_user_id())
  );
--> statement-breakpoint
