      OR EXISTS (SELECT 1 FROM public.sales_documents d WHERE d.tenant_id = sales_document_links.tenant_id AND d.id = sales_document_links.from_document_id)
    )
  );
--> statement-breakpoint
CREATE POLICY sales_document_links_insert ON public.sales_document_links FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'sales_manager', 'salesperson')
    AND created_by = (SELECT app.current_user_id())
    AND EXISTS (SELECT 1 FROM public.sales_documents d WHERE d.tenant_id = sales_document_links.tenant_id AND d.id = sales_document_links.to_document_id)
    AND EXISTS (SELECT 1 FROM public.sales_documents d WHERE d.tenant_id = sales_document_links.tenant_id AND d.id = sales_document_links.from_document_id)
  );
--> statement-breakpoint
CREATE POLICY sales_document_links_delete ON public.sales_document_links FOR DELETE TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'sales_manager', 'salesperson')
    AND EXISTS (SELECT 1 FROM public.sales_documents d WHERE d.tenant_id = sales_document_links.tenant_id AND d.id = sales_document_links.to_document_id)
  );
