  BEFORE INSERT OR UPDATE OR DELETE ON public.sales_lines
  FOR EACH ROW EXECUTE FUNCTION app.check_sales_document_part();
--> statement-breakpoint
ALTER TABLE public.sales_lines ENABLE ALWAYS TRIGGER sales_lines_check;
