-- ── hand-written: a customer's credit limit is the owner's to change ────────────────────────────
-- An order over the limit needs the owner. Whoever can change the limit can lift it, sell, and
-- put it back, so changing the limit of a customer that already exists needs the owner too.
-- Whoever adds a customer sets its first limit; that is in the audit log under their name.
CREATE FUNCTION app.check_customer_credit_limit() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_role public.member_role;
BEGIN
  IF session_user = 'postgres' THEN
    RETURN NEW;
  END IF;
  -- The company and the role are asked together, for this row: a statement can change which
  -- company the session is in between two of its rows.
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NEW.credit_limit IS DISTINCT FROM OLD.credit_limit THEN
    v_role := app.tenant_role();
    IF v_role IS DISTINCT FROM 'owner' THEN
      RAISE EXCEPTION 'only an owner changes a customer''s credit limit' USING ERRCODE = 'SE055';
    END IF;
    -- Written here, so the change is in the log however it was made.
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
      VALUES (NEW.tenant_id, app.current_user_id(), v_role, 'customer.credit_limit', 'customer', NEW.id,
        jsonb_build_object('name', OLD.name, 'creditLimit', OLD.credit_limit::text), jsonb_build_object('name', NEW.name, 'creditLimit', NEW.credit_limit::text));
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_customer_credit_limit() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER customers_credit_limit_check
  BEFORE UPDATE ON public.customers
  FOR EACH ROW EXECUTE FUNCTION app.check_customer_credit_limit();
--> statement-breakpoint
ALTER TABLE public.customers ENABLE ALWAYS TRIGGER customers_credit_limit_check;
--> statement-breakpoint

-- ── hand-written: the audit log's own time, and the rows only the database writes ───────────────
-- The app writes most audit rows itself, in the transaction that makes the change. Two things
-- are not left to it: when a row was written, and the rows that the database's own functions
-- and guards write (a journal posted or reversed; a sales document submitted, held, sent back,
-- cancelled or approved over the credit limit; a credit limit changed). A row of one of those
-- kinds written by the app's role directly would only look like the real thing, so it is
-- refused. Inside those functions the role at work is the functions' owner, not the app's.
CREATE FUNCTION app.check_audit_row() RETURNS trigger
  LANGUAGE plpgsql SET search_path = ''
  AS $$
BEGIN
  IF session_user = 'postgres' THEN
    RETURN NEW;
  END IF;
  NEW.at := now();
  IF current_user = session_user AND NEW.action ~ '^(journal\.(post|reverse)|sales_[a-z_]+\.(submit|cancel|hold|release|credit_override)|customer\.credit_limit)$' THEN
    RAISE EXCEPTION 'that audit row is written by the database itself' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_audit_row() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER audit_log_check
  BEFORE INSERT ON public.audit_log
  FOR EACH ROW EXECUTE FUNCTION app.check_audit_row();
--> statement-breakpoint
ALTER TABLE public.audit_log ENABLE ALWAYS TRIGGER audit_log_check;
